void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float boxsize=min(iResolution.x*0.5,iResolution.y*0.5);
    vec2 centre;
    int quadrant=0;
    if(fragCoord.x*2.0<iResolution.x){
        centre.x=iResolution.x*0.25;
    }
    else{
        centre.x=iResolution.x*0.75;
        quadrant+=1;
    }
    if(fragCoord.y*2.0<iResolution.y){
        centre.y=iResolution.y*0.25;
    }
    else{
        centre.y=iResolution.y*0.75;
        quadrant+=2;
    }
    float time=iTime;
    vec3 c=vec3(1.0,0.8,0.8);
    if(quadrant==1){
        time=floor(time*200.0)/200.0;
        c=vec3(1.0,1.0,1.0);
    }
    if(quadrant==2){
        time=floor(time*100.0)/100.0;
        c=vec3(0.8,1.0,0.8);
    }
    if(quadrant==3){
        time=floor(time*50.0)/50.0;
        c=vec3(0.8,0.8,1.0);
    }
    time*=1.0;
    vec2 along=vec2(sin(time),cos(time));
    vec2 normal=vec2(cos(time),-sin(time));
    vec2 end1=centre+along*boxsize*0.4;
    vec2 end2=centre-along*boxsize*0.4;
    float radius=boxsize*0.05;
    float radiuss=radius*radius;
    float sumd=0.0;
    float sumdp=0.0;
    float a;
    float b;
    for(a=-0.5;a<1.0;a+=1.0){
        for(b=-0.5;b<1.0;b+=1.0){
            vec2 pixelcorner=fragCoord+vec2(a,b);
            float d=distance(end1,pixelcorner)-radius;
            d=min(d,distance(end2,pixelcorner)-radius);
            float inlinesegment=dot(pixelcorner-centre,along);
            if(abs(inlinesegment)<boxsize*0.4){
                d=min(d,abs(dot(normal,pixelcorner-centre))-radius);
            }
            sumd+=d;
            sumdp+=abs(d);
        }
    }
    float fill=((-sumd/sumdp)+1.0)*0.5;
    fragColor = vec4(c*fill,1.0);
}
